import 'dart:ui' show Color;

/// Build-time white-label configuration for one salon.
///
/// The concrete values live in `tenant_config.g.dart`, generated by
/// `dart run tool/white_label.dart --tenant <slug>`. A few values can also be
/// overridden at build time with `--dart-define` (see [TenantConfig.resolve]).
class TenantConfig {
  const TenantConfig({
    required this.appName,
    required this.tenantSlug,
    required this.apiBaseUrl,
    required this.bundleId,
    required this.primary,
    required this.primaryDark,
    required this.accent,
    required this.ink,
    required this.background,
    required this.splashColor,
    this.logoAsset,
    this.defaultLocale = 'en',
    this.supportWhatsapp,
  });

  /// Display name of the app ("Maison Lumière").
  final String appName;

  /// Salon slug sent as the `X-Tenant` header.
  final String tenantSlug;

  /// Origin of the backend, without the `/api/v1` suffix.
  final String apiBaseUrl;

  /// Android applicationId / iOS bundle identifier of the client app.
  final String bundleId;

  final Color primary;
  final Color primaryDark;
  final Color accent;
  final Color ink;
  final Color background;
  final Color splashColor;

  /// Asset path of the logo bundled in the app (optional).
  final String? logoAsset;
  final String defaultLocale;

  /// WhatsApp number (E.164 without +) for the "chat with us" shortcut.
  final String? supportWhatsapp;

  /// Full API root, e.g. `https://lumiere.luxesalon.app/api/v1`.
  String get apiRoot {
    final base = apiBaseUrl.endsWith('/') ? apiBaseUrl.substring(0, apiBaseUrl.length - 1) : apiBaseUrl;
    return '$base/api/v1';
  }

  /// Applies `--dart-define` overrides:
  /// `API_BASE_URL`, `TENANT`, `APP_NAME`.
  TenantConfig resolve() {
    const apiOverride = String.fromEnvironment('API_BASE_URL');
    const tenantOverride = String.fromEnvironment('TENANT');
    const nameOverride = String.fromEnvironment('APP_NAME');

    return copyWith(
      apiBaseUrl: apiOverride.isEmpty ? null : apiOverride,
      tenantSlug: tenantOverride.isEmpty ? null : tenantOverride,
      appName: nameOverride.isEmpty ? null : nameOverride,
    );
  }

  TenantConfig copyWith({
    String? appName,
    String? tenantSlug,
    String? apiBaseUrl,
    String? bundleId,
    Color? primary,
    Color? primaryDark,
    Color? accent,
    Color? ink,
    Color? background,
    Color? splashColor,
    String? logoAsset,
    String? defaultLocale,
    String? supportWhatsapp,
  }) {
    return TenantConfig(
      appName: appName ?? this.appName,
      tenantSlug: tenantSlug ?? this.tenantSlug,
      apiBaseUrl: apiBaseUrl ?? this.apiBaseUrl,
      bundleId: bundleId ?? this.bundleId,
      primary: primary ?? this.primary,
      primaryDark: primaryDark ?? this.primaryDark,
      accent: accent ?? this.accent,
      ink: ink ?? this.ink,
      background: background ?? this.background,
      splashColor: splashColor ?? this.splashColor,
      logoAsset: logoAsset ?? this.logoAsset,
      defaultLocale: defaultLocale ?? this.defaultLocale,
      supportWhatsapp: supportWhatsapp ?? this.supportWhatsapp,
    );
  }
}
